def find_path(graph, start, goal): 
    def dfs(start, goal, path, visited): 
        path.append(start) 
        if start == goal: 
            return path 
        visited.add(start) 
        for neighbor in graph.get(start, []): 
            if neighbor not in visited: 
                new_path = dfs(neighbor, goal, path.copy(), visited.copy()) 
                if new_path: 
                    return new_path 
        path.pop() 
        return None 

    visited = set() 
    return dfs(start, goal, [], visited) 

